const app = document.querySelector('#app');
const dialog = document.querySelector('#dialog');
const directions = {
  f:{name:'Figma',desc:'Les trois écrans de la maquette CS2 Utilities.',words:'Onyx · Orange · Bleu ardoise'},
  a:{name:'Tactique',tag:'Chaque détail compte.',desc:'Un poste d’analyse précis. Grand lecteur à gauche, carte et lancers à droite. Base onyx, accents corail, jaune, rose et bleu.',words:'Palette Onyx · Vidéo 75 %'},
  b:{name:'Studio',tag:'De l’espace pour analyser.',desc:'Un atelier clair et calme. Surfaces ivoire, typographie généreuse et une bibliothèque facile à parcourir.',words:'Ivoire / Vert forêt · Aéré · Éditorial'},
  c:{name:'Focus',tag:'Le jeu au premier plan.',desc:'Une salle de visionnage immersive. Grand lecteur, radar secondaire et sélection des clips en bandeau.',words:'Encre / Corail · Immersif · Cinéma'}
};
let state={variant:'a',page:'library',type:'all',filter:'all',frequency:'all',round:'all',selected:0,heat:false,zoom:100,phase:'idle',zone:'A Main',drawing:false,empty:false};
let clips = window.prototypeData.clips.map(c=>({...c}));
const icons={library:'▦',export:'↗',zones:'⌖',components:'◫'};
const pages={library:'Vidéothèque',export:'Nouvel export',zones:'Éditeur de zones',components:'Composants'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,attrs='',cls='')=>`<button class="${cls}" ${attrs}>${label}</button>`;
const primary=(label,attrs='')=>btn(label,attrs,'primary');
const selectedClip=()=>clips.find(c=>c.id===state.selected)||clips[0];
function notify(message){let el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function navigate(){const p=new URLSearchParams(location.hash.slice(1));if(!p.has('v'))return overview();state.variant=directions[p.get('v')]?p.get('v'):'a';state.page=pages[p.get('p')]?p.get('p'):'library';render();}
function go(page=state.page,variant=state.variant){location.hash=`v=${variant}&p=${page}`;}
function overview(){document.body.className='overview';app.innerHTML=`<main class="explorations"><div class="overview-top"><a class="brand" href="#"><span class="brand-icon">U</span> UTILITAIRES CS2</a><span class="eyebrow">ÉTUDE VISUELLE / 01</span></div><div class="overview-intro"><span class="eyebrow">EXPLORE LES DIRECTIONS VISUELLES.</span><h1>Une autre façon<br>de lire le jeu<span>.</span></h1><p>Explore les pages, essaie les composants, compare les ambiances.<br>Choisis ensuite la direction à développer.</p></div><div class="direction-grid">${Object.entries(directions).map(([v,d],i)=>`<a class="direction direction-${v}" href="#v=${v}&p=library"><div class="miniature"><img src="assets/preview-${v}.jpg" alt="Aperçu de la vidéothèque ${d.name}" onerror="this.style.display='none'"><div class="mini-fallback"><span class="mini-nav">U&nbsp; /&nbsp; ${d.name.toUpperCase()}</span><div class="mini-body"><img src="assets/de_ancient.png" alt=""><div><span></span><span></span><span></span></div></div></div><span class="preview-index">0${i+1}</span></div><div class="direction-copy"><div class="direction-name"><h2>${d.name}</h2><span>↗</span></div><p>${d.desc}</p><small>${d.words}</small><strong>Explorer la variante ${v.toUpperCase()} <span>→</span></strong></div></a>`).join('')}</div><footer class="overview-footer"><span><i class="live-dot"></i> Prototypes interactifs</span><span>Copies de médias locaux · Actions de traitement simulées · Site existant inchangé</span></footer></main>`;}
function nav(){return Object.entries(pages).map(([id,label])=>`<a href="#v=${state.variant}&p=${id}" class="${id===state.page?'active':''}" ${id===state.page?'aria-current="page"':''}><span>${icons[id]}</span>${label}</a>`).join('');}
function render(){if(state.variant==='f'){renderFigma();return;}document.body.className=`theme-${state.variant}${state.variant==='a'&&state.page==='library'?' tactical-library':''}`;const d=directions[state.variant];app.innerHTML=`<div class="proto-bar"><a href="#">← Tous les prototypes</a><div class="variant-switch" aria-label="Variantes">${Object.entries(directions).map(([v,x])=>`<a href="#v=${v}&p=${state.page}" class="${v===state.variant?'active':''}" ${v===state.variant?'aria-current="true"':''}><b>${v.toUpperCase()}</b> ${x.name}</a>`).join('')}</div><span class="proto-label">PROTOTYPE · Actions simulées</span></div><div class="shell"><aside class="sidebar"><a class="brand" href="#v=${state.variant}&p=library"><span class="brand-icon">U</span><span>Utilitaires<span class="brand-sub">COUNTER-STRIKE 2</span></span></a><span class="nav-label">ESPACE DE TRAVAIL</span><nav>${nav()}</nav><div class="sidebar-bottom"><div class="local-status"><i class="live-dot"></i> Bibliothèque locale</div><p>Ton jeu. Tes repères.</p><small>Direction ${state.variant.toUpperCase()} · ${d.name}</small></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Espace de travail <span>/</span> <strong>${pages[state.page]}</strong></div><nav class="topnav">${nav()}</nav><div class="top-actions"><span class="local-status"><i class="live-dot"></i> En local</span><span class="avatar">AK</span></div></header><main class="page page-${state.page}">${state.page==='library'?library():state.page==='export'?exportPage():state.page==='zones'?zonesPage():components()}</main><footer class="app-footer"><span>UTILITAIRES CS2</span><span>${d.words}</span></footer></div></div>`;bind();}
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-action">${action}</div></div>`;}
function filtered(){return state.empty?[]:clips.filter(c=>(state.type==='all'||c.kind===state.type)&&(state.filter==='all'||state.filter==='favorites'&&c.favorite||state.filter==='unseen'&&!c.seen)&&(state.frequency==='all'||c.frequency===state.frequency)&&(state.round==='all'||String(c.round)===state.round)&&(state.variant!=='f'||!state.search||c.title.toLowerCase().includes(state.search.toLowerCase())));}
function filters(){return `<div class="filterbar"><div class="segmented" role="group" aria-label="Type d’utilitaire">${[['all','Tous'],['smoke','Smoke'],['flash','Flash'],['molo','Molotov'],['he','HE']].map(([v,t])=>btn((v==='all'?'':`<i class="kind-dot ${v}"></i>`)+t,`data-type="${v}" aria-pressed="${state.type===v}"`,state.type===v?'active':'')).join('')}</div><div class="filter-options">${btn('☆ Favoris',`data-filter="favorites" aria-pressed="${state.filter==='favorites'}"`,state.filter==='favorites'?'active':'')}${btn('◉ À traiter',`data-filter="unseen" aria-pressed="${state.filter==='unseen'}"`,state.filter==='unseen'?'active':'')}<label class="sr-only" for="frequency">Fréquence</label><select id="frequency"><option value="all">Fréquence : toutes</option>${['Rare','Commun','Très fréquent'].map(t=>`<option ${state.frequency===t?'selected':''}>${t}</option>`).join('')}</select><label class="sr-only" for="round">Round</label><select id="round"><option value="all">Tous les rounds</option><option value="1" ${state.round==='1'?'selected':''}>Round 1</option></select></div></div>`;}
function library(){const items=filtered();if(items.length&&!items.some(c=>c.id===state.selected))state.selected=items[0].id;const c=selectedClip();return `${heading('LA PRÉPARATION FAIT LA DIFFÉRENCE','Ta vidéothèque.','Explore les lancers. Trouve ton prochain avantage.',`<label class="map-choice">Carte <select id="map"><option>Ancient</option></select></label>${btn('⌖ Éditer les zones','data-go="zones"')}${primary('＋ Nouvel export','data-go="export"')}`)}<div class="library-summary"><span><strong>${clips.length}</strong> clips de démonstration</span><span><strong>01</strong> carte</span><span><strong>${clips.filter(c=>c.favorite).length.toString().padStart(2,'0')}</strong> favoris</span><span class="summary-right">SPIRIT <span class="vs">VS</span> FURIA <i class="kind-dot smoke"></i> Ancient</span></div>${filters()}${!items.length?`<div class="empty-state"><span>⌕</span><h2>Aucun lancer pour ces filtres</h2><p>Essaie un autre utilitaire ou réinitialise ta sélection.</p>${primary('Réinitialiser les filtres','data-action="reset"')}</div>`:`<div class="library-workspace">${state.variant==='a'?`${videoPanel(c,false)}<aside class="tactical-inspector" aria-label="Carte, lancers et commandes">${radarPanel()}${clipList(items)}${consolePanel(c)}</aside>`:`${radarPanel()}${videoPanel(c)}${clipList(items)}`}</div>`}`;}
function radarPanel(editor=false){return `<section class="panel radar-panel"><div class="panel-title"><h2>${editor?'Ancient':'Lecture tactique'}</h2>${editor?'<span class="badge">Niveau haut</span>':'<span class="badge">ANCIENT</span>'}</div><div class="radar-tools">${editor?btn('＋ Nouvelle zone','data-action="draw"'): `<label>Points <select id="points-mode"><option>Activation</option><option>Départ</option></select></label>${btn('Heatmap',`data-action="heat" aria-pressed="${state.heat}"`,state.heat?'active':'')}`}</div><div class="radar-image ${state.heat?'heat-on':''} ${editor?'editor-map':''}"><div class="map-stage" style="transform:scale(${state.zoom/100})"><img src="assets/de_ancient.png" alt="Radar de la carte Ancient" draggable="false">${editor?`<svg viewBox="0 0 100 100" role="img" aria-label="Zones de démonstration"><polygon class="zone-polygon" points="24,22 42,22 45,41 30,48 23,36"/><polygon class="zone-polygon secondary-zone" points="57,25 75,25 78,42 59,45"/>${state.drawing?'<polyline class="zone-polygon draft" points="35,58 53,53 58,71 39,76 35,58"/>':''}<g class="vertices">${[[24,22],[42,22],[45,41],[30,48],[23,36]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r=".8"/>`).join('')}</g><text x="28" y="34">${escapeHTML(state.zone)}</text><text x="62" y="35">B Site</text></svg>`:filtered().map(c=>{const i=c.id;return `<button class="map-pin ${c.id===state.selected?'selected':''} ${c.kind}" data-clip="${c.id}" style="left:${[71.4,83.7,81.2][i]}%;top:${[34.2,34.3,51.1][i]}%" aria-label="Sélectionner ${escapeHTML(c.title)}">${i+1}</button>`;}).join('')+`<svg class="route" viewBox="0 0 100 100" aria-hidden="true"><path d="M 69 56 Q 62 43 ${[71.4,83.7,81.2][state.selected]} ${[34.2,34.3,51.1][state.selected]}"/><circle cx="69" cy="56" r="1"/></svg>`}</div><span class="map-coordinates">DE_ANCIENT / ${editor?'ÉDITION':'ACTIVATIONS'}</span><div class="zoom">${btn('−','data-zoom="-10" aria-label="Réduire le zoom"')}<output>${state.zoom} %</output>${btn('＋','data-zoom="10" aria-label="Augmenter le zoom"')}</div></div><div class="radar-caption"><span><i class="kind-dot smoke"></i> ${editor?'Zone sélectionnée':'Smoke'} &nbsp; <i class="kind-dot molo"></i> ${editor?'Autre zone':'Molotov'}</span><span>${editor?'Sommets modifiables au stade final':'Clique sur un repère ↗'}</span></div></section>`;}
const mouseModes = {left:'Clic gauche', right:'Clic droit', middle:'Clic gauche et droit simultanés'};
function mouseBadge(mode) {
  const label = mouseModes[mode];
  return `<kbd class="throw-key" title="${label}"><span class="mouse-icon mouse-${mode}" aria-hidden="true"></span><span class="sr-only">${label}</span></kbd>`;
}
function throwControls(controls) {
  if (!controls) return '';
  const keys = [
    ...(controls.directions ?? []).filter(key => ['W','Q','S','D'].includes(key)),
    controls.walk && 'SHIFT', controls.crouch && 'CROUCH', controls.jump && 'ESPACE'
  ].filter(Boolean);
  const badges = Object.hasOwn(mouseModes, controls.mouse) ? [mouseBadge(controls.mouse)] : [];
  badges.push(...keys.map(key => `<kbd class="throw-key">${key}</kbd>`));
  if (!badges.length) return '';
  return `<div class="throw-controls" role="group" aria-label="Commandes du lancer"><span class="throw-label" aria-hidden="true">Commandes</span>${badges.join('')}</div>`;
}
function videoPanel(c,includeConsole=true){return `<section class="panel video-panel"><div class="panel-title"><div><span class="eyebrow">${c.kind==='smoke'?'SMOKE':'MOLOTOV'} / ROUND ${c.round}</span><h2>${escapeHTML(c.title)}</h2></div>${btn('Modifier la zone','data-action="rename"','subtle')}</div><div class="video-wrap"><video controls playsinline preload="metadata" poster="${c.poster}" src="${c.video}"></video><span class="video-marker">POV / ${escapeHTML(c.player)}</span></div><div class="clip-info"><div class="player-avatar">${c.player.slice(0,1)}</div><div><strong>${escapeHTML(c.player)}</strong><small>Spirit vs FURIA · Ancient</small></div><span class="duration">${c.duration.toFixed(1)} s</span>${btn(c.favorite?'★':'☆',`data-action="favorite" aria-label="${c.favorite?'Retirer des favoris':'Ajouter aux favoris'}" aria-pressed="${c.favorite}"`,'favorite')}</div><div class="clip-actions">${primary('↗ Vidéo 9:16','data-action="portrait"')}${throwControls(c.lineup?.controls)}${btn('Supprimer','data-action="delete"','danger subtle')}</div>${includeConsole?consolePanel(c):''}</section>`;}
function consolePanel(c){return `<div class="console"><div><span class="eyebrow">CONSOLE CS2</span><code>setpos ${c.lineup.position.map(x=>x.toFixed(1)).join(' ')}; setang ${c.lineup.angles.map(x=>x.toFixed(1)).join(' ')} 0</code></div>${btn('Copier','data-action="copy"')}</div>`;}
function clipList(items){return `<section class="panel clips-panel"><div class="panel-title"><h2>Les lancers <span class="count">${items.length.toString().padStart(2,'0')}</span></h2><span class="muted">Sélection manuelle</span></div><div class="clip-list">${items.map(c=>`<button class="clip-card ${c.id===state.selected?'selected':''}" data-clip="${c.id}" aria-pressed="${c.id===state.selected}"><div class="clip-thumb"><img src="${c.poster}" alt="Aperçu du lancer de ${escapeHTML(c.player)}"><span>${c.duration.toFixed(1)} s</span></div><div class="clip-card-text"><span class="clip-card-title">${escapeHTML(c.title)} <span>${c.favorite?'★':''}</span></span><small>${escapeHTML(c.player)} <span>· Round ${c.round}</span></small><div class="clip-tags"><span class="badge"><i class="kind-dot ${c.kind}"></i> ${c.kind==='molo'?'Molotov':'Smoke'}</span><span class="frequency">${c.frequency}</span></div></div><span class="clip-arrow">↗</span></button>`).join('')}</div><div class="list-foot">${items.filter(c=>!c.seen).length} à traiter <span>Échantillon de ta bibliothèque</span></div></section>`;}
function exportPage(){return `${heading('DE LA DÉMO AU REPÈRE','Prépare ta prochaine session.','Transforme tes démos en clips de lancers, prêts à analyser.')}<div class="export-workspace"><section class="panel import-panel"><div class="panel-title"><h2>Nouvel export</h2><span class="step-number">01 — 03</span></div><label class="upload-zone" for="demo-file"><span class="upload-icon">↥</span><h3>Dépose tes démos ici</h3><p>Fichiers .dem ou archives HLTV .rar</p><span class="button-look">Parcourir les fichiers</span><input type="file" id="demo-file" accept=".dem,.rar" multiple><small id="file-label">ou explore avec un fichier de démonstration</small></label><div class="form-row"><label>Utilitaire<select id="export-kind"><option>Tous les utilitaires</option><option>Smoke</option><option>Flash</option><option>Molotov</option><option>HE</option></select></label><label>Maximum par carte<input type="number" min="1" placeholder="Tous les clips"></label></div><details><summary>Options de rendu <span>＋</span></summary><div class="option-detail"><label><input type="checkbox" checked> Ignorer les doublons</label><p>Format source 16:9 · Audio du jeu conservé</p></div></details>${primary('Générer les clips ↗','data-action="generate"')}<p class="form-hint"><i class="live-dot"></i> Pour le rendu réel, garde Steam ouvert.</p></section><div class="export-side">${progress()}<section class="panel history-panel"><div class="panel-title"><h2>Galeries récentes</h2><span class="badge">DÉMONSTRATION</span></div>${[['Spirit vs FURIA','Ancient · 3 clips','Aujourd’hui'],['Vitality vs Falcons','Mirage · 18 clips','Hier'],['G2 vs Falcons','Nuke · 12 clips','Hier']].map(([name,meta,date])=>`<button class="history-item" data-go="library"><span class="file-symbol">▤</span><span><strong>${name}</strong><small>${meta}</small></span><span class="history-date">${date} ↗</span></button>`).join('')}</section></div></div>`;}
function progress(){const active=state.phase!=='idle';const stopped=state.phase==='paused';return `<section class="panel progress-panel"><div class="panel-title"><h2>${!active?'Un flux simple.':state.phase==='complete'?'Tes clips sont prêts.':stopped?'Traitement en pause':'Capture en cours'}</h2><span class="badge ${active?'accent':''}">${active?'SIMULATION':'LE WORKFLOW'}</span></div>${!active?`<ol class="workflow"><li><b>01</b><div><strong>Importe tes démos</strong><p>Un match ou plusieurs archives à la fois.</p></div></li><li><b>02</b><div><strong>Capture les lancers</strong><p>Les utilitaires sont repérés et découpés.</p></div></li><li><b>03</b><div><strong>Retrouve tes repères</strong><p>Clips, radar et commandes au même endroit.</p></div></li></ol>`:`<p class="progress-file">spirit-vs-furia-m1-ancient.dem</p><div class="progress-heading"><span>${state.phase==='complete'?'Export terminé':stopped?'En attente de reprise':'Capture des utilitaires'}</span><strong>${state.phase==='complete'?'100':'64'} %</strong></div><progress max="100" value="${state.phase==='complete'?100:64}"></progress><p class="muted">${state.phase==='complete'?'3 clips disponibles dans la vidéothèque.':'Démo 1 / 1 · Clip 2 / 3'}</p><div class="progress-actions">${state.phase==='complete'?primary('Ouvrir la galerie','data-go="library"'):btn(stopped?'▶ Reprendre':'Ⅱ Pause','data-action="pause"')}${state.phase!=='complete'?btn('Annuler','data-action="cancel"','danger subtle')+btn('Voir l’état terminé','data-action="complete"','subtle'):''}</div><details><summary>Journal du traitement</summary><code>[démo] Analyse terminée<br>[capture] 3 utilitaires détectés<br>[rendu] Clip 2 sur 3</code></details>`}</section>`;}
function zonesPage(){return `${heading('CARTOGRAPHIE PERSONNELLE','Donne un nom à tes repères.','Organise les callouts et retrouve les bons lancers plus vite.',btn('← Vidéothèque','data-go="library"'))}<div class="zone-workspace">${radarPanel(true)}<section class="panel zone-inspector"><span class="eyebrow">INSPECTEUR DE ZONE</span><h2>${escapeHTML(state.zone)}</h2><label>Carte<select><option>Ancient</option></select></label><label>Niveau<select><option>Haut</option></select></label><div class="zone-list">${['A Main','A Site','B Site','Mid'].map((n,i)=>btn(`<i class="zone-color color-${i}"></i><span>${n}</span><small>${i+1}</small>`,`data-zone="${n}"`,n===state.zone?'selected':'')).join('')}</div><label>Nom de la zone<input id="zone-name" maxlength="64" value="${escapeHTML(state.zone)}"></label><div class="inline-actions">${primary('Enregistrer','data-action="save-zone"')}${btn('Supprimer','data-action="delete-zone"','danger subtle')}</div><section class="layers"><span class="eyebrow">SUPERPOSITIONS</span><p>La première zone passe devant les autres.</p><div><span>01 &nbsp; ${escapeHTML(state.zone)}</span><span>↑ ↓</span></div><div><span>02 &nbsp; A Site</span><span>↑ ↓</span></div></section><p class="form-hint">${state.drawing?'Tracé de démonstration affiché. Enregistre pour nommer cette zone.':'Sélectionne une zone pour examiner son style et ses propriétés.'}</p></section></div>`;}
function components(){return `${heading('LE SYSTÈME VISUEL','Des détails qui font équipe.','Les composants et leurs états, dans la direction '+directions[state.variant].name+'.')}<div class="component-grid"><section class="panel"><span class="eyebrow">01 / ACTIONS</span><h2>Boutons & interactions</h2><div class="component-row">${primary('Générer les clips','data-action="generate-demo"')}${btn('Éditer les zones','data-go="zones"')}${btn('Indisponible','disabled')}${btn('Supprimer','data-action="delete"','danger')}</div><div class="component-row">${btn('☆ Favoris','data-action="favorite"')}${btn('Sélectionné','aria-pressed="true"','active')}<kbd>ESPACE</kbd>${['left','right','middle'].map(mouseBadge).join('')}</div></section><section class="panel"><span class="eyebrow">02 / DONNÉES</span><h2>Badges & fréquences</h2><div class="component-row">${['smoke','flash','molo','he'].map(t=>`<span class="badge"><i class="kind-dot ${t}"></i>${{smoke:'Smoke',flash:'Flash',molo:'Molotov',he:'HE'}[t]}</span>`).join('')}</div><div class="component-row"><span class="badge accent">Très fréquent</span><span class="badge">Commun</span><span class="badge">Rare</span><span class="badge"><i class="live-dot"></i> Vu</span></div></section><section class="panel"><span class="eyebrow">03 / FORMULAIRES</span><h2>Filtres & champs</h2><label>Nom du callout<input placeholder="Ex. Entrée du site A"></label><label>Carte<select><option>Ancient</option><option>Mirage</option><option>Nuke</option></select></label><div class="component-row">${btn('Attribution d’une zone','data-action="rename"')}</div></section><section class="panel"><span class="eyebrow">04 / RETOURS</span><h2>États & messages</h2><p class="message success">✓ Export terminé. 3 clips ajoutés à la bibliothèque.</p><p class="message warning">Ⅱ Traitement en pause. Reprends quand tu es prêt.</p><p class="message error">! Aucun fichier sélectionné. Ajoute une démo.</p><div class="component-row">${btn('Notification de succès','data-action="success"')}${btn('Aperçu de l’état vide','data-action="empty"')}</div></section><section class="panel palette-panel"><span class="eyebrow">05 / IDENTITÉ</span><h2>Couleurs & typographie</h2><div class="swatches">${(state.variant==='a'?['onyx','amaranth','tomato','tuscan','pacific']:['bg','surface','accent','ink','muted']).map(v=>`<span><i style="background:var(--${v})"></i>${v}</span>`).join('')}</div><p class="type-sample">Lire le jeu.<br>Préparer la suite.</p><span class="eyebrow">ABCDEFGHIJKLMNOPQRSTUVWXYZ · 0123456789</span></section><section class="panel"><span class="eyebrow">06 / CARTE VIDÉO</span><h2>Le lancer, en un regard</h2><div class="component-clip">${clipList([selectedClip()])}</div><p class="form-hint">Survol · sélection · favori · métadonnées</p></section></div>`;}
function openDialog(kind){const c=selectedClip();dialog.dataset.kind=kind;dialog.innerHTML=kind==='rename'?`<form id="rename-form"><span class="eyebrow">REPÈRES PERSONNELS</span><h2>Zone du lancer</h2><p>Attribue un callout à ce clip.</p><label>Nom de la zone<input id="rename-input" value="${escapeHTML(c.title)}" maxlength="64" required></label><div class="dialog-actions">${btn('Annuler','type="button" data-close')}${btn('Automatique','type="button" data-auto')}${primary('Enregistrer','type="submit"')}</div></form>`:`<span class="eyebrow">${kind==='delete-zone'?'ZONE DE CALLOUT':'BIBLIOTHÈQUE'}</span><h2>${kind==='delete-zone'?'Supprimer cette zone ?':'Supprimer ce clip ?'}</h2><p>${kind==='delete-zone'?'La zone sélectionnée sera retirée de cet aperçu.':'Dans le site final, cette action effacera le MP4 du PC.'}</p><p class="simulation-note">Prototype : aucun fichier réel ne sera supprimé.</p><div class="dialog-actions">${btn('Annuler','data-close')}${btn('Simuler la suppression','data-confirm','danger')}</div>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();if(kind==='rename'){dialog.querySelector('[data-auto]').onclick=()=>{c.title=['Entrée du site A','Couper la rotation','Contrôler le mid'][c.id];dialog.close();render();};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();c.title=dialog.querySelector('input').value.trim()||c.title;dialog.close();render();notify('Nom du clip mis à jour dans le prototype.');};}else dialog.querySelector('[data-confirm]').onclick=()=>{dialog.close();if(kind==='delete-zone'){state.zone='A Site';render();}notify('Suppression simulée · Tes fichiers sont conservés.');};dialog.showModal();}
function bind(){document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));document.querySelectorAll('[data-type]').forEach(el=>el.onclick=()=>{state.type=el.dataset.type;state.empty=false;render();});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{state.filter=state.filter===el.dataset.filter?'all':el.dataset.filter;render();});document.querySelectorAll('[data-clip]').forEach(el=>el.onclick=()=>{state.selected=Number(el.dataset.clip);selectedClip().seen=true;render();});document.querySelectorAll('[data-zone]').forEach(el=>el.onclick=()=>{state.zone=el.dataset.zone;render();});document.querySelectorAll('[data-zoom]').forEach(el=>el.onclick=()=>{state.zoom=Math.max(100,Math.min(180,state.zoom+Number(el.dataset.zoom)));render();});for(const id of ['frequency','round']){const el=document.getElementById(id);if(el)el.onchange=()=>{state[id]=el.value;render();};}const file=document.querySelector('#demo-file');if(file)file.onchange=()=>{document.querySelector('#file-label').textContent=[...file.files].map(f=>f.name).join(', ')||'Aucun fichier sélectionné';};document.querySelector('#points-mode')?.addEventListener('change',()=>notify('Vue des points modifiée · Illustration du filtre.'));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{switch(el.dataset.action){case 'favorite':selectedClip().favorite=!selectedClip().favorite;render();break;case 'heat':state.heat=!state.heat;render();break;case 'portrait':notify('Rendu 9:16 simulé · Aucun encodage lancé.');break;case 'delete':case 'rename':case 'delete-zone':openDialog(el.dataset.action);break;case 'copy':try{await navigator.clipboard.writeText(document.querySelector('.console code').textContent);notify('Commandes CS2 copiées.');}catch{notify('Sélectionne le texte de la console pour le copier.');}break;case 'generate':state.phase='running';render();notify('Aperçu du traitement · Aucun rendu réel lancé.');break;case 'generate-demo':state.phase='running';go('export');break;case 'pause':state.phase=state.phase==='paused'?'running':'paused';render();break;case 'cancel':state.phase='idle';render();notify('Simulation du traitement annulée.');break;case 'complete':state.phase='complete';render();break;case 'reset':state.type='all';state.filter='all';state.frequency='all';state.round='all';state.search='';state.empty=false;render();break;case 'draw':state.drawing=!state.drawing;render();break;case 'save-zone':state.zone=document.querySelector('#zone-name').value.trim()||state.zone;state.drawing=false;render();notify('Zone enregistrée dans cet aperçu uniquement.');break;case 'success':notify('Export terminé · Tes clips sont prêts.');break;case 'empty':state.empty=true;go('library');break;}});}
document.addEventListener('dragover',event=>{if(event.target.closest('.upload-zone'))event.preventDefault();});
document.addEventListener('drop',event=>{const zone=event.target.closest('.upload-zone');if(!zone)return;event.preventDefault();const names=[...event.dataTransfer.files].filter(f=>/\.(dem|rar)$/i.test(f.name)).map(f=>f.name);document.querySelector('#file-label').textContent=names.join(', ')||'Choisis un fichier .dem ou .rar';});
window.addEventListener('hashchange',navigate);
navigate();
